<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Your booking | Triple R Gensan</title><link rel="stylesheet" href="/assets/css/app.css"><script src="/assets/js/rental-booking.js" defer></script></head><body><main class="page-shell" data-booking-url="/api/rentals/booking-context"><section class="panel"><p class="eyebrow">Triple R Gensan</p><h1>Your rental booking</h1><p id="booking-context-status" role="status" aria-live="polite">Checking your secure booking access…</p><dl id="booking-context" hidden><div><dt>Agreement</dt><dd data-field="agreement_id"></dd></div><div><dt>Status</dt><dd data-field="status"></dd></div><div><dt>Vehicle</dt><dd data-field="vehicle"></dd></div><div><dt>Rental dates</dt><dd><span data-field="start_date"></span> to <span data-field="end_date"></span></dd></div><div><dt>Duration</dt><dd><span data-field="rental_days"></span> day(s)</dd></div><div><dt>Base amount</dt><dd>₱<span data-field="base_amount"></span></dd></div></dl><p class="muted">Contact the rental office for changes to your reservation.</p></section></main></body></html>
